<?php
class EmptyPackaging extends Model
{
 protected $table='empty_packaging_items';
 public function references(){return['items'=>$this->query("SELECT * FROM empty_packaging_items WHERE status='active' AND deleted_at IS NULL ORDER BY code")->fetchAll(),'sites'=>$this->query("SELECT id,code,name FROM sites WHERE status='active' AND deleted_at IS NULL ORDER BY name")->fetchAll(),'suppliers'=>$this->query("SELECT id,name FROM suppliers WHERE status IN('active','validated') AND deleted_at IS NULL ORDER BY name")->fetchAll()];}
 public function dashboard(){ $p=[];$scope=Auth::siteClause('st.site_id',$p);return$this->query("SELECT st.*,i.code,i.name,i.unit_capacity_kg,s.code site_code,COALESCE((SELECT SUM(m.quantity) FROM empty_packaging_movements m WHERE m.stock_id=st.id AND m.movement_type='consumption' AND m.movement_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)),0) consumed_30d,COALESCE((SELECT SUM(m.quantity) FROM empty_packaging_movements m WHERE m.stock_id=st.id AND m.movement_type='defective' AND m.movement_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)),0) defective_30d FROM empty_packaging_stocks st JOIN empty_packaging_items i ON i.id=st.packaging_item_id JOIN sites s ON s.id=st.site_id WHERE st.deleted_at IS NULL{$scope} ORDER BY s.code,i.code",$p)->fetchAll();}
 public function pendingPurchases(){$p=[];$s=Auth::siteClause('p.site_id',$p);return$this->query("SELECT p.*,sp.name supplier_name,si.code site_code FROM empty_packaging_purchases p JOIN suppliers sp ON sp.id=p.supplier_id JOIN sites si ON si.id=p.site_id WHERE p.status IN('draft','approved','partially_received') AND p.deleted_at IS NULL{$s} ORDER BY p.id DESC",$p)->fetchAll();}
 public function pendingRequests(){$p=[];$s=Auth::siteClause('r.site_id',$p);return$this->query("SELECT r.*,si.code site_code FROM empty_packaging_requests r JOIN sites si ON si.id=r.site_id WHERE r.status IN('submitted','approved') AND r.deleted_at IS NULL{$s} ORDER BY r.id DESC",$p)->fetchAll();}
 public function pendingTransfers(){$site=Auth::currentSiteId();$p=[];$where='';if($site!==null){$where=' AND (t.source_site_id=:s OR t.destination_site_id=:d)';$p=['s'=>$site,'d'=>$site];}return$this->query("SELECT t.*,ss.code source_code,ds.code destination_code FROM empty_packaging_transfers t JOIN sites ss ON ss.id=t.source_site_id JOIN sites ds ON ds.id=t.destination_site_id WHERE t.status IN('draft','in_transit') AND t.deleted_at IS NULL{$where} ORDER BY t.id DESC",$p)->fetchAll();}
 public function operations(){ $p=[];$scope=Auth::siteClause('p.site_id',$p);return$this->query("SELECT 'ACHAT' kind,p.id,p.purchase_number number,p.status,p.ordered_at operation_at,s.code site_code FROM empty_packaging_purchases p JOIN sites s ON s.id=p.site_id WHERE p.deleted_at IS NULL{$scope} UNION ALL SELECT 'DAE',r.id,r.request_number,r.status,r.needed_at,s.code FROM empty_packaging_requests r JOIN sites s ON s.id=r.site_id WHERE r.deleted_at IS NULL".str_replace('p.site_id','r.site_id',$scope)." ORDER BY operation_at DESC",$p)->fetchAll();}
 public function createPurchase(array$d,array$user){$site=Auth::requireCurrentSite();$this->db->beginTransaction();try{$n='ACH-EMB-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO empty_packaging_purchases(site_id,supplier_id,purchase_number,status,ordered_at,created_by) VALUES(:site,:supplier,:number,'draft',NOW(),:user)",['site'=>$site,'supplier'=>$d['supplier_id'],'number'=>$n,'user'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO empty_packaging_purchase_lines(purchase_id,packaging_item_id,ordered_quantity,unit_cost) VALUES(:purchase,:item,:qty,:cost)',['purchase'=>$id,'item'=>$d['packaging_item_id'],'qty'=>$d['quantity'],'cost'=>$d['unit_cost']]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BC',$site,'empty_packaging_purchases',$id,'draft',date('Y-m-d H:i:s'),$user);$this->logActivity('create_purchase','empty-packaging','empty_packaging_purchases',$id,'Création achat emballages.',null,$d,$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function setMinimum($stockId,$minimum,array$user){$this->db->beginTransaction();try{$s=$this->row('SELECT * FROM empty_packaging_stocks WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$stockId]);if(!$s)throw new RuntimeException('Stock introuvable.');Auth::requireSiteAccess($s['site_id']);$minimum=(int)$minimum;if($minimum<0)throw new RuntimeException('Seuil invalide.');$this->query('UPDATE empty_packaging_stocks SET minimum_quantity=:minimum WHERE id=:id',['minimum'=>$minimum,'id'=>$stockId]);$this->logActivity('update_minimum','empty-packaging','empty_packaging_stocks',$stockId,'Modification du seuil minimum.',['minimum_quantity'=>$s['minimum_quantity']],['minimum_quantity'=>$minimum],$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approvePurchase($id,array$user){$this->db->beginTransaction();try{$p=$this->row('SELECT * FROM empty_packaging_purchases WHERE id=? AND deleted_at IS NULL FOR UPDATE',[$id]);if(!$p||$p['status']!=='draft')throw new RuntimeException('Achat non approuvable.');Auth::requireSiteAccess($p['site_id']);if((int)$p['created_by']===(int)$user['id'])throw new RuntimeException('Le créateur ne peut pas approuver.');$this->query("UPDATE empty_packaging_purchases SET status='approved',approved_by=:user WHERE id=:id",['user'=>$user['id'],'id'=>$id]);$this->approveDocument('BC','empty_packaging_purchases',$id,$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receivePurchase($id,array$user,$key){$this->db->beginTransaction();try{$existing=$this->row('SELECT id FROM empty_packaging_receipts WHERE idempotency_key=? FOR UPDATE',[$key]);if($existing){$this->db->commit();return$existing['id'];}$p=$this->row('SELECT * FROM empty_packaging_purchases WHERE id=? FOR UPDATE',[$id]);if(!$p||!in_array($p['status'],['approved','partially_received'],true))throw new RuntimeException('Achat non réceptionnable.');Auth::requireSiteAccess($p['site_id']);$line=$this->row('SELECT * FROM empty_packaging_purchase_lines WHERE purchase_id=? FOR UPDATE',[$id]);$qty=(int)$line['ordered_quantity']-(int)$line['received_quantity'];if($qty<=0)throw new RuntimeException('Achat déjà reçu.');$n='REC-EMB-'.date('YmdHis').'-'.random_int(100,999);$this->query('INSERT INTO empty_packaging_receipts(purchase_id,receipt_number,idempotency_key,received_at,received_by) VALUES(:purchase,:number,:key,NOW(),:user)',['purchase'=>$id,'number'=>$n,'key'=>$key,'user'=>$user['id']]);$rid=$this->db->lastInsertId();$this->query('INSERT INTO empty_packaging_receipt_lines(receipt_id,purchase_line_id,quantity) VALUES(:receipt,:line,:qty)',['receipt'=>$rid,'line'=>$line['id'],'qty'=>$qty]);$stock=$this->lockStock($p['site_id'],$line['packaging_item_id']);$before=(int)$stock['physical_quantity'];$after=$before+$qty;$newCost=$after?((($before*(float)$stock['average_unit_cost'])+($qty*(float)$line['unit_cost']))/$after):(float)$line['unit_cost'];$this->query('UPDATE empty_packaging_stocks SET physical_quantity=:qty,average_unit_cost=:cost WHERE id=:id',['qty'=>$after,'cost'=>$newCost,'id'=>$stock['id']]);$this->movement($stock,'purchase_receipt',$qty,$before,$after,'empty_packaging_receipts',$rid,$user,$line['unit_cost']);$this->query("UPDATE empty_packaging_purchase_lines SET received_quantity=received_quantity+:qty WHERE id=:id",['qty'=>$qty,'id'=>$line['id']]);$this->query("UPDATE empty_packaging_purchases SET status='received' WHERE id=:id",['id'=>$id]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BRA',$p['site_id'],'empty_packaging_receipts',$rid,'validated',date('Y-m-d H:i:s'),$user);$this->db->commit();return$rid;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createRequest(array$d,array$user){$site=Auth::requireCurrentSite();$this->db->beginTransaction();try{$n='DAE-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO empty_packaging_requests(site_id,request_number,status,needed_at,justification,created_by) VALUES(:site,:number,'submitted',:needed,:why,:user)",['site'=>$site,'number'=>$n,'needed'=>$d['needed_at'],'why'=>$d['justification'],'user'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO empty_packaging_request_lines(request_id,packaging_item_id,requested_quantity) VALUES(:request,:item,:qty)',['request'=>$id,'item'=>$d['packaging_item_id'],'qty'=>$d['quantity']]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('DAE',$site,'empty_packaging_requests',$id,'submitted',date('Y-m-d H:i:s'),$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveRequest($id,array$user){$this->db->beginTransaction();try{$r=$this->row('SELECT * FROM empty_packaging_requests WHERE id=? FOR UPDATE',[$id]);if(!$r||$r['status']!=='submitted')throw new RuntimeException('DAE non approuvable.');if((int)$r['created_by']===(int)$user['id'])throw new RuntimeException('Le demandeur ne peut pas approuver.');Auth::requireSiteAccess($r['site_id']);$l=$this->row('SELECT * FROM empty_packaging_request_lines WHERE request_id=? FOR UPDATE',[$id]);$s=$this->lockStock($r['site_id'],$l['packaging_item_id']);$available=(int)$s['physical_quantity']-(int)$s['reserved_quantity'];if($available<(int)$l['requested_quantity'])throw new RuntimeException('Stock disponible insuffisant.');$this->query('UPDATE empty_packaging_stocks SET reserved_quantity=reserved_quantity+:qty WHERE id=:id',['qty'=>$l['requested_quantity'],'id'=>$s['id']]);$this->query("UPDATE empty_packaging_requests SET status='approved',approved_by=:user WHERE id=:id",['user'=>$user['id'],'id'=>$id]);$this->approveDocument('DAE','empty_packaging_requests',$id,$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function issue($id,array$user){$this->db->beginTransaction();try{$r=$this->row('SELECT * FROM empty_packaging_requests WHERE id=? FOR UPDATE',[$id]);if(!$r||$r['status']!=='approved')throw new RuntimeException('DAE non délivrable.');Auth::requireSiteAccess($r['site_id']);$l=$this->row('SELECT * FROM empty_packaging_request_lines WHERE request_id=? FOR UPDATE',[$id]);$s=$this->lockStock($r['site_id'],$l['packaging_item_id']);$qty=(int)$l['requested_quantity'];if((int)$s['physical_quantity']<$qty||(int)$s['reserved_quantity']<$qty)throw new RuntimeException('Stock réservé incohérent.');$n='BSE-'.date('YmdHis').'-'.random_int(100,999);$this->query('INSERT INTO empty_packaging_issues(request_id,issue_number,issued_at,issued_by) VALUES(:request,:number,NOW(),:user)',['request'=>$id,'number'=>$n,'user'=>$user['id']]);$iid=$this->db->lastInsertId();$this->query('INSERT INTO empty_packaging_issue_lines(issue_id,request_line_id,quantity) VALUES(:issue,:line,:qty)',['issue'=>$iid,'line'=>$l['id'],'qty'=>$qty]);$before=(int)$s['physical_quantity'];$after=$before-$qty;$this->query('UPDATE empty_packaging_stocks SET physical_quantity=:after,reserved_quantity=reserved_quantity-:qty,operational_quantity=operational_quantity+:qty2 WHERE id=:id',['after'=>$after,'qty'=>$qty,'qty2'=>$qty,'id'=>$s['id']]);$this->movement($s,'issue',$qty,$before,$after,'empty_packaging_issues',$iid,$user);$this->query("UPDATE empty_packaging_request_lines SET issued_quantity=:qty WHERE id=:id",['qty'=>$qty,'id'=>$l['id']]);$this->query("UPDATE empty_packaging_requests SET status='fulfilled' WHERE id=:id",['id'=>$id]);require_once dirname(__DIR__).'/services/DocumentService.php';(new DocumentService($this->db))->register('BSE',$r['site_id'],'empty_packaging_issues',$iid,'validated',date('Y-m-d H:i:s'),$user);$this->db->commit();return$iid;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function recordDefect(array$d,array$user){$site=Auth::requireCurrentSite();$this->db->beginTransaction();try{$s=$this->lockStock($site,$d['packaging_item_id']);$qty=(int)$d['quantity'];if((int)$s['physical_quantity']<$qty)throw new RuntimeException('Stock insuffisant.');$this->query('INSERT INTO empty_packaging_defects(site_id,packaging_item_id,quantity,reason,detected_at,created_by) VALUES(:site,:item,:qty,:reason,NOW(),:user)',['site'=>$site,'item'=>$d['packaging_item_id'],'qty'=>$qty,'reason'=>$d['reason'],'user'=>$user['id']]);$id=$this->db->lastInsertId();$before=(int)$s['physical_quantity'];$after=$before-$qty;$this->query('UPDATE empty_packaging_stocks SET physical_quantity=:qty WHERE id=:id',['qty'=>$after,'id'=>$s['id']]);$this->movement($s,'defective',$qty,$before,$after,'empty_packaging_defects',$id,$user);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function createTransfer(array$d,array$user){$source=Auth::requireCurrentSite();$dest=(int)$d['destination_site_id'];if($source===$dest)throw new RuntimeException('Sites distincts requis.');$this->db->beginTransaction();try{$n='TREMB-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO empty_packaging_transfers(transfer_number,source_site_id,destination_site_id,status,created_by) VALUES(:number,:source,:dest,'draft',:user)",['number'=>$n,'source'=>$source,'dest'=>$dest,'user'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO empty_packaging_transfer_lines(transfer_id,packaging_item_id,quantity) VALUES(:transfer,:item,:qty)',['transfer'=>$id,'item'=>$d['packaging_item_id'],'qty'=>$d['quantity']]);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function approveTransfer($id,array$user){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM empty_packaging_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='draft')throw new RuntimeException('Transfert non approuvable.');Auth::requireSiteAccess($t['source_site_id']);if((int)$t['created_by']===(int)$user['id'])throw new RuntimeException('Le créateur ne peut pas approuver le transfert.');$l=$this->row('SELECT * FROM empty_packaging_transfer_lines WHERE transfer_id=? FOR UPDATE',[$id]);$s=$this->lockStock($t['source_site_id'],$l['packaging_item_id']);$q=(int)$l['quantity'];if((int)$s['physical_quantity']-(int)$s['reserved_quantity']<$q)throw new RuntimeException('Stock source insuffisant.');$b=(int)$s['physical_quantity'];$this->query('UPDATE empty_packaging_stocks SET physical_quantity=physical_quantity-:q WHERE id=:id',['q'=>$q,'id'=>$s['id']]);$this->movement($s,'transfer_out',$q,$b,$b-$q,'empty_packaging_transfers',$id,$user);$this->query("UPDATE empty_packaging_transfers SET status='in_transit',approved_by=:user,shipped_at=NOW() WHERE id=:id",['user'=>$user['id'],'id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function receiveTransfer($id,array$user){$this->db->beginTransaction();try{$t=$this->row('SELECT * FROM empty_packaging_transfers WHERE id=? FOR UPDATE',[$id]);if(!$t||$t['status']!=='in_transit')throw new RuntimeException('Transfert non réceptionnable.');Auth::requireSiteAccess($t['destination_site_id']);$l=$this->row('SELECT * FROM empty_packaging_transfer_lines WHERE transfer_id=? FOR UPDATE',[$id]);$s=$this->lockStock($t['destination_site_id'],$l['packaging_item_id']);$q=(int)$l['quantity'];$b=(int)$s['physical_quantity'];$this->query('UPDATE empty_packaging_stocks SET physical_quantity=physical_quantity+:q WHERE id=:id',['q'=>$q,'id'=>$s['id']]);$this->movement($s,'transfer_in',$q,$b,$b+$q,'empty_packaging_transfers',$id,$user);$this->query("UPDATE empty_packaging_transfers SET status='received',received_at=NOW() WHERE id=:id",['id'=>$id]);$this->db->commit();}catch(Exception$e){$this->db->rollBack();throw$e;}}
 public function transfer(array$d,array$user){$source=Auth::requireCurrentSite();$dest=(int)$d['destination_site_id'];if($source===$dest)throw new RuntimeException('Sites distincts requis.');Auth::requireSiteAccess($dest);$this->db->beginTransaction();try{$ss=$this->lockStock($source,$d['packaging_item_id']);$ds=$this->lockStock($dest,$d['packaging_item_id']);$qty=(int)$d['quantity'];if((int)$ss['physical_quantity']-(int)$ss['reserved_quantity']<$qty)throw new RuntimeException('Stock source disponible insuffisant.');$n='TREMB-'.date('YmdHis').'-'.random_int(100,999);$this->query("INSERT INTO empty_packaging_transfers(transfer_number,source_site_id,destination_site_id,status,created_by,approved_by,shipped_at,received_at) VALUES(:number,:source,:dest,'received',:user,:approver,NOW(),NOW())",['number'=>$n,'source'=>$source,'dest'=>$dest,'user'=>$user['id'],'approver'=>$user['id']]);$id=$this->db->lastInsertId();$this->query('INSERT INTO empty_packaging_transfer_lines(transfer_id,packaging_item_id,quantity) VALUES(:transfer,:item,:qty)',['transfer'=>$id,'item'=>$d['packaging_item_id'],'qty'=>$qty]);$sb=(int)$ss['physical_quantity'];$db=(int)$ds['physical_quantity'];$this->query('UPDATE empty_packaging_stocks SET physical_quantity=physical_quantity-:qty WHERE id=:id',['qty'=>$qty,'id'=>$ss['id']]);$this->query('UPDATE empty_packaging_stocks SET physical_quantity=physical_quantity+:qty,average_unit_cost=:cost WHERE id=:id',['qty'=>$qty,'cost'=>$ss['average_unit_cost'],'id'=>$ds['id']]);$this->movement($ss,'transfer_out',$qty,$sb,$sb-$qty,'empty_packaging_transfers',$id,$user);$this->movement($ds,'transfer_in',$qty,$db,$db+$qty,'empty_packaging_transfers',$id,$user);$this->db->commit();return$id;}catch(Exception$e){$this->db->rollBack();throw$e;}}
 private function lockStock($site,$item){$s=$this->row('SELECT * FROM empty_packaging_stocks WHERE site_id=? AND packaging_item_id=? AND deleted_at IS NULL FOR UPDATE',[$site,$item]);if(!$s){$this->query('INSERT INTO empty_packaging_stocks(site_id,packaging_item_id) VALUES(:site,:item)',['site'=>$site,'item'=>$item]);$s=$this->row('SELECT * FROM empty_packaging_stocks WHERE site_id=? AND packaging_item_id=? FOR UPDATE',[$site,$item]);}return$s;}
 private function movement($s,$type,$qty,$before,$after,$ref,$id,$user,$cost=null){$this->query('INSERT INTO empty_packaging_movements(stock_id,movement_type,quantity,stock_before,stock_after,unit_cost,reference_type,reference_id,movement_at,created_by) VALUES(:stock,:type,:qty,:before,:after,:cost,:ref,:id,NOW(),:user)',['stock'=>$s['id'],'type'=>$type,'qty'=>$qty,'before'=>$before,'after'=>$after,'cost'=>$cost,'ref'=>$ref,'id'=>$id,'user'=>$user['id']]);}
 private function approveDocument($code,$entity,$id,$user){$d=$this->query('SELECT d.id,d.status FROM documents d JOIN document_types dt ON dt.id=d.document_type_id WHERE dt.code=:code AND d.entity_type=:entity AND d.entity_id=:id FOR UPDATE',['code'=>$code,'entity'=>$entity,'id'=>$id])->fetch();if($d&&$d['status']!=='approved'){$this->query("UPDATE documents SET status='approved',validated_by=:user,validated_at=NOW() WHERE id=:id",['user'=>$user['id'],'id'=>$d['id']]);$this->query('INSERT INTO document_status_history(document_id,old_status,new_status,changed_by,reason) VALUES(:doc,:old,\'approved\',:user,\'Approbation métier\')',['doc'=>$d['id'],'old'=>$d['status'],'user'=>$user['id']]);}}
 private function row($sql,$p){$s=$this->db->prepare($sql);$s->execute($p);return$s->fetch();}
}
